import java.util.*;import ama.task.*;import ama.contract.TaskContracts.Permit;import org.springframework.jdbc.core.JdbcTemplate;
class Task09Fix01SettleOriginal {public static void main(String[] a)throws Exception{var source=ama.minutes.Task09Source.open();var j=new JdbcTemplate(source);j.setQueryTimeout(2);String task="fa172992-cbf0-4527-a638-ab6e4853b819",execution="3ea4befa-a586-4170-aa2c-5923fd678ae4",reservation="120e2368-6b9b-46eb-9e5f-f53df037580c",operation="da316d18-5827-4ca3-95e8-387d6935f2d9";if(!"STALE".equals(j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,task))||!"SUCCEEDED".equals(j.queryForObject("SELECT state FROM external_execution WHERE id=? AND task_id=? AND operation_id=?",String.class,execution,task,operation))||j.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Integer.class,task)!=0)throw new IllegalStateException("Original fact guard failed");var fences=new JdbcSubjectFences(source,Set.of("MEETING"));var outbox=new JdbcOutbox(source,Map.of());var queue=new JdbcTaskQueue(source,fences,outbox,Map.of());var external=new JdbcExternalOperations(queue);var permits=new JdbcModelPermitPool(external,Map.of(),(t,m,d)->{throw new IllegalStateException();});var row=j.queryForMap("SELECT model,config_revision,settled_at FROM model_reservation WHERE id=? AND execution_id=?",reservation,execution);if(row.get("settled_at")!=null)throw new IllegalStateException("Original permit already settled");boolean settled=permits.settled(new Permit(reservation,(String)row.get("model"),execution,((Number)row.get("config_revision")).longValue(),null));var receipt=new TreeMap<String,Object>();receipt.put("task",task);receipt.put("execution",execution);receipt.put("operation",operation);receipt.put("reservation",reservation);receipt.put("settledResult",settled);receipt.put("unsettledCount",j.queryForObject("SELECT COUNT(*) FROM model_reservation WHERE id=? AND execution_id=? AND settled_at IS NULL",Integer.class,reservation,execution));receipt.put("lookupOrPostPerformed",false);receipt.put("completedUtc",java.time.Instant.now().toString());System.out.println(new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(receipt));if(!settled||!receipt.get("unsettledCount").equals(0))throw new IllegalStateException("Original permit remains unsettled");}}
